import { get, handleApiError, post } from '@helpers/httpClient';

import { mapWorkoutTrackMarkupToFront } from '../@mappers/workoutTrackMarkup.mapper';
import {
  IWorkoutTrackMarkupAddDTO,
  IWorkoutTrackMarkupDTO,
  IWorkoutTrackMarkupUpdateDTO,
} from '../@types/DTO/workoutTrackMarkup.dto.types';
import { IWorkoutTrackMarkup } from '../@types/workoutTrackMarkup.types';

export const getWorkoutTrackMarkup = async (
  id_workout_track: number,
): Promise<IWorkoutTrackMarkup[]> => {
  const res = await get('/ajax/workouts/markup/list.php', { id_workout_track }).then<
    IWorkoutTrackMarkupDTO[]
  >(handleApiError);
  return res.map(mapWorkoutTrackMarkupToFront);
};

export const getWorkoutTrackMarkupForCsvWorkoutIds = async (
  workout_track_ids: string,
): Promise<IWorkoutTrackMarkup[]> => {
  const res = await get('/ajax/workouts/markup/list.php', { workout_track_ids }).then<
    IWorkoutTrackMarkupDTO[]
  >(handleApiError);
  return res.map(mapWorkoutTrackMarkupToFront);
};

export const addWorkoutTrackMarkup = async (data: IWorkoutTrackMarkupAddDTO): Promise<number> => {
  const res = await post('/ajax/workouts/markup/add.php', data).then<{ id: number }>(
    handleApiError,
  );
  return +res.id;
};
export const updateWorkoutTrackMarkup = async (
  data: IWorkoutTrackMarkupUpdateDTO,
): Promise<boolean> => {
  const res = await post('/ajax/workouts/markup/edit.php', data).then<{ affected: number }>(
    handleApiError,
  );
  return +res.affected > 0;
};

export const deleteWorkoutTrackMarkup = async (id: number): Promise<boolean> => {
  const res = await post('/ajax/workouts/markup/delete.php', { id }).then<{ affected: number }>(
    handleApiError,
  );
  return +res.affected > 0;
};
