import { getDateFromSQLAsUTC, getSQLDate } from '@helpers/dateHelper';

import {
  IWorkoutTrackMarkupAddDTO,
  IWorkoutTrackMarkupDTO,
  IWorkoutTrackMarkupUpdateDTO,
} from '../@types/DTO/workoutTrackMarkup.dto.types';
import { IWorkoutTrackMarkup } from '../@types/workoutTrackMarkup.types';

export const mapWorkoutTrackMarkupToFront = (
  backData: IWorkoutTrackMarkupDTO,
): IWorkoutTrackMarkup => {
  return {
    id: +backData.id,
    id_workout_track: +backData.id_workout_track,

    name: backData.name,
    isBreak: +backData.is_break === 1,

    utcD1: getDateFromSQLAsUTC(backData.date_from),
    utcD2: getDateFromSQLAsUTC(backData.date_to),

    created_at: new Date(backData.created_at),
    updated_at: backData.updated_at ? new Date(backData.updated_at) : null,
    author: {
      id: +backData.author_id,
      name: backData.author_name,
      surname: backData.author_surname,
      photo: backData.author_photo,
    },
  };
};

export const mapWorkoutTrackMarkupToUpdateDTO = (
  markup: IWorkoutTrackMarkup,
): IWorkoutTrackMarkupUpdateDTO => {
  return {
    id: markup.id,
    name: markup.name,
    is_break: markup.isBreak ? 1 : 0,
    date_from: getSQLDate(markup.utcD1, true),
    date_to: getSQLDate(markup.utcD2, true),
  };
};

export const mapWorkoutTrackMarkupToAddDto = (
  markup: IWorkoutTrackMarkup,
  id_workout_track: number,
): IWorkoutTrackMarkupAddDTO => {
  return {
    id_workout_track,
    name: markup.name,
    is_break: markup.isBreak ? 1 : 0,
    date_from: getSQLDate(markup.utcD1, true),
    date_to: getSQLDate(markup.utcD2, true),
  };
};
